@namespace sv_ef4a060ba6cd49868effbf0e7a4fb9b1.Components.Pages.Apply

<div class="step-indicator">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var index = i;
        var cssClass = GetStepClass(index);
        <div class="step-item @cssClass" @onclick="() => OnStepClick(index)">
            <div class="step-circle">
                @if (CompletedSteps.Contains(index))
                {
                    <span>&#10003;</span>
                }
                else
                {
                    <span>@(index + 1)</span>
                }
            </div>
            <div class="step-label">@StepNames[index]</div>
        </div>
        @if (index < StepNames.Count - 1)
        {
            <div class="step-connector @(CompletedSteps.Contains(index) ? "completed" : "")"></div>
        }
    }
</div>

@code {
    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepSelected { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private string GetStepClass(int index)
    {
        if (index == CurrentStep) return "active";
        if (CompletedSteps.Contains(index)) return "completed";
        return "dimmed";
    }

    private async Task OnStepClick(int index)
    {
        if (CompletedSteps.Contains(index))
        {
            await OnStepSelected.InvokeAsync(index);
        }
    }
}

@namespace sv_ef4a060ba6cd49868effbf0e7a4fb9b1.Components.Pages.Apply

<div class="work-entry-form">
    <div class="form-row">
        <div class="form-group">
            <label>Company Name</label>
            <input type="text" value="@Entry.Company"
                   @onchange="e => Update(Entry with { Company = e.Value?.ToString() ?? string.Empty })" />
        </div>
        <div class="form-group">
            <label>Job Title</label>
            <input type="text" value="@Entry.Title"
                   @onchange="e => Update(Entry with { Title = e.Value?.ToString() ?? string.Empty })" />
        </div>
    </div>
    <div class="form-row">
        <div class="form-group">
            <label>Start Date</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => Update(Entry with { StartDate = DateTime.Parse(e.Value?.ToString() ?? DateTime.Today.ToString("yyyy-MM-dd")) })" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@(Entry.EndDate?.ToString("yyyy-MM-dd") ?? string.Empty)"
                   disabled="@IsCurrent"
                   @onchange="e => Update(Entry with { EndDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null })" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent"
                       @onchange="e => OnCurrentChanged((bool)(e.Value ?? false))" />
                Current position
            </label>
        </div>
    </div>
    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Entry.Description"
                  @onchange="e => Update(Entry with { Description = e.Value?.ToString() ?? string.Empty })"></textarea>
    </div>
    @if (CanRemove)
    {
        <button type="button" class="btn-remove" @onclick="OnRemove">Remove</button>
    }
</div>

@code {
    [Parameter, EditorRequired] public WorkEntry Entry { get; set; } = default!;
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntry> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate is null;

    private void OnCurrentChanged(bool isCurrent)
    {
        var updated = isCurrent
            ? Entry with { EndDate = null }
            : Entry with { EndDate = DateTime.Today };
        Update(updated);
    }

    private async Task Update(WorkEntry updated)
    {
        await OnEntryChanged.InvokeAsync(updated);
    }
}

