@namespace sv_ef4a060ba6cd49868effbf0e7a4fb9b1.Components.Pages.Apply

<div class="step-content">
    <h2>Personal Information</h2>

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" value="@FullName" @onchange="e => FullName = e.Value?.ToString() ?? string.Empty" />
    </div>
    <div class="form-group">
        <label>Email *</label>
        <input type="email" value="@Email" @onchange="e => Email = e.Value?.ToString() ?? string.Empty" />
        @if (!string.IsNullOrEmpty(_emailError))
        {
            <span class="error">@_emailError</span>
        }
    </div>
    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" value="@Phone" @onchange="e => Phone = e.Value?.ToString() ?? string.Empty" />
    </div>
    <div class="form-group">
        <label>Address *</label>
        <textarea rows="2" value="@Address" @onchange="e => Address = e.Value?.ToString() ?? string.Empty"></textarea>
    </div>

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="error">@_validationError</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn-primary" @onclick="HandleNext" disabled="@_isValidating">
            @(_isValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = string.Empty;
    [Parameter] public string Email { get; set; } = string.Empty;
    [Parameter] public string Phone { get; set; } = string.Empty;
    [Parameter] public string Address { get; set; } = string.Empty;
    [Parameter] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter] public IApplicationService ApplicationService { get; set; } = default!;

    private string _validationError = string.Empty;
    private string _emailError = string.Empty;
    private bool _isValidating;

    private async Task HandleNext()
    {
        _validationError = string.Empty;
        _emailError = string.Empty;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email)
            || string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            _validationError = "All fields are required.";
            return;
        }

        _isValidating = true;
        var emailValid = await ApplicationService.ValidateEmailAsync(Email);
        _isValidating = false;

        if (!emailValid)
        {
            _emailError = "Please enter a valid email address.";
            return;
        }

        await OnNext.InvokeAsync(new PersonalInfo(FullName, Email, Phone, Address));
    }
}

@namespace sv_ef4a060ba6cd49868effbf0e7a4fb9b1.Components.Pages.Apply

<div class="step-content">
    <h2>Work History</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <div class="entry-card">
            <h4>Position @(index + 1)</h4>
            <WorkEntryForm Entry="@Entries[index]"
                           CanRemove="@(Entries.Count > 1)"
                           OnEntryChanged="e => UpdateEntry(index, e)"
                           OnRemove="() => RemoveEntry(index)" />
        </div>
    }

    <button type="button" class="btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="error">@_validationError</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntry> Entries { get; set; } = new();
    [Parameter] public EventCallback<List<WorkEntry>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string _validationError = string.Empty;

    private void UpdateEntry(int index, WorkEntry updated)
    {
        Entries[index] = updated;
    }

    private void AddEntry()
    {
        Entries.Add(new WorkEntry(string.Empty, string.Empty, DateTime.Today, null, string.Empty));
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        _validationError = string.Empty;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                _validationError = "Each position must have at least a company name and job title.";
                return;
            }
        }

        await OnNext.InvokeAsync(Entries);
    }
}

@namespace sv_ef4a060ba6cd49868effbf0e7a4fb9b1.Components.Pages.Apply

<div class="step-content">
    <h2>References</h2>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <div class="entry-card">
            <h4>Reference @(index + 1)</h4>
            <ReferenceForm Entry="@References[index]"
                           CanRemove="@(References.Count > 2)"
                           OnEntryChanged="e => UpdateReference(index, e)"
                           OnRemove="() => RemoveReference(index)" />
        </div>
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="error">@_validationError</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<Reference> References { get; set; } = new();
    [Parameter] public EventCallback<List<Reference>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string _validationError = string.Empty;

    private void UpdateReference(int index, Reference updated)
    {
        References[index] = updated;
    }

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new Reference(string.Empty, string.Empty, string.Empty, string.Empty));
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        _validationError = string.Empty;

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Email))
            {
                _validationError = "Each reference must have at least a name and email.";
                return;
            }
        }

        await OnNext.InvokeAsync(References);
    }
}

@namespace sv_ef4a060ba6cd49868effbf0e7a4fb9b1.Components.Pages.Apply

<div class="step-content">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <label>Write your cover letter</label>
        <textarea rows="12" maxlength="2000" value="@CoverLetter"
                  @oninput="e => UpdateCoverLetter(e.Value?.ToString() ?? string.Empty)"></textarea>
        <div class="char-count">@CoverLetter.Length / 2000 characters</div>
