@namespace sv_ef4a060ba6cd49868effbf0e7a4fb9b1.Components.Pages.Apply

<div class="step-content">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <label>Write your cover letter</label>
        <textarea rows="12" maxlength="2000" value="@CoverLetter"
                  @oninput="e => UpdateCoverLetter(e.Value?.ToString() ?? string.Empty)"></textarea>
        <div class="char-count">@CoverLetter.Length / 2000 characters</div>
    </div>

    <div class="step-buttons">
        <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public string CoverLetter { get; set; } = string.Empty;
    [Parameter] public EventCallback<string> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private void UpdateCoverLetter(string value)
    {
        CoverLetter = value.Length > 2000 ? value[..2000] : value;
    }

    private async Task HandleNext()
    {
        await OnNext.InvokeAsync(CoverLetter);
    }
}

@namespace sv_ef4a060ba6cd49868effbf0e7a4fb9b1.Components.Pages.Apply

<div class="step-content">
    <h2>Review & Submit</h2>

    @if (_submitted)
    {
        <div class="confirmation">
            <h3>&#10003; Application Submitted Successfully!</h3>
            <p>Your application ID is: <strong>@_applicationId</strong></p>
            <p>We will review your application and get back to you soon.</p>
        </div>
    }
    else
    {
        <div class="review-section">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Name</dt><dd>@Personal.FullName</dd>
                <dt>Email</dt><dd>@Personal.Email</dd>
                <dt>Phone</dt><dd>@Personal.Phone</dd>
                <dt>Address</dt><dd>@Personal.Address</dd>
            </dl>
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>Work History</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in Work.Entries)
            {
                <div class="review-entry">
                    <strong>@entry.Title</strong> at @entry.Company
                    <br />
                    <span class="date-range">
                        @entry.StartDate.ToString("MMM yyyy") &ndash;
                        @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")
                    </span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>References</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="review-entry">
                    <strong>@r.Name</strong> (@r.Relationship)
                    <br />@r.Email | @r.Phone
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>Cover Letter</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@CoverLetter</p>
        </div>

        @if (!string.IsNullOrEmpty(_errorMessage))
        {
            <div class="error">@_errorMessage</div>
        }

        <div class="step-buttons">
            <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
            <button type="button" class="btn-primary" @onclick="HandleSubmit" disabled="@_isSubmitting">
                @(_isSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public PersonalInfo Personal { get; set; } = default!;
    [Parameter] public WorkHistory Work { get; set; } = default!;
    [Parameter] public List<Reference> References { get; set; } = new();
    [Parameter] public string CoverLetter { get; set; } = string.Empty;
    [Parameter] public IApplicationService ApplicationService { get; set; } = default!;
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<int> OnEditStep { get; set; }

    private bool _isSubmitting;
    private bool _submitted;
    private int _applicationId;
    private string _errorMessage = string.Empty;

    private async Task HandleSubmit()
    {
        _isSubmitting = true;
        _errorMessage = string.Empty;

        try
        {
            var application = new JobApplication(Personal, Work, References, CoverLetter);
            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        catch (Exception ex)
        {
            _errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _isSubmitting = false;
        }
    }
}

