@page "/apply"
@namespace sv_ef4a060ba6cd49868effbf0e7a4fb9b1.Components.Pages.Apply
@using sv_ef4a060ba6cd49868effbf0e7a4fb9b1.Services
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@_currentStep"
                   CompletedSteps="@_completedSteps"
                   OnStepSelected="GoToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@_personalInfo.FullName"
                              Email="@_personalInfo.Email"
                              Phone="@_personalInfo.Phone"
                              Address="@_personalInfo.Address"
                              ApplicationService="@ApplicationService"
                              OnNext="HandlePersonalInfoNext" />
            break;
        case 1:
            <WorkHistoryStep Entries="@_workEntries"
                             OnNext="HandleWorkHistoryNext"
                             OnBack="GoBack" />
            break;
        case 2:
            <ReferencesStep References="@_references"
                            OnNext="HandleReferencesNext"
                            OnBack="GoBack" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@_coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="GoBack" />
            break;
        case 4:
            <ReviewStep Personal="@_personalInfo"
                        Work="@(new WorkHistory(_workEntries))"
                        References="@_references"
                        CoverLetter="@_coverLetter"
                        ApplicationService="@ApplicationService"
                        OnBack="GoBack"
                        OnEditStep="GoToStep" />
            break;
    }
</div>

@code {
    private int _currentStep;
    private HashSet<int> _completedSteps = new();

    private PersonalInfo _personalInfo = new(string.Empty, string.Empty, string.Empty, string.Empty);
    private List<WorkEntry> _workEntries = new() { new(string.Empty, string.Empty, DateTime.Today, null, string.Empty) };
    private List<Reference> _references = new()
    {
        new(string.Empty, string.Empty, string.Empty, string.Empty),
        new(string.Empty, string.Empty, string.Empty, string.Empty)
    };
    private string _coverLetter = string.Empty;

    private void HandlePersonalInfoNext(PersonalInfo info)
    {
        _personalInfo = info;
        _completedSteps.Add(0);
        _currentStep = 1;
    }

    private void HandleWorkHistoryNext(List<WorkEntry> entries)
    {
        _workEntries = entries;
        _completedSteps.Add(1);
        _currentStep = 2;
    }

    private void HandleReferencesNext(List<Reference> references)
    {
        _references = references;
        _completedSteps.Add(2);
        _currentStep = 3;
    }

    private void HandleCoverLetterNext(string coverLetter)
    {
        _coverLetter = coverLetter;
        _completedSteps.Add(3);
        _currentStep = 4;
    }

    private void GoToStep(int step)
    {
        _currentStep = step;
    }

    private void GoBack()
    {
        if (_currentStep > 0)
            _currentStep--;
    }
}

