             <input type="text" value="@Entry.Title"
                    @onchange="e => Update(Entry with { Title = e.Value?.ToString() ?? string.Empty })" />
         </div>
     </div>
     <div class="form-row">
         <div class="form-group">
             <label>Start Date</label>
             <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                    @onchange="e => Update(Entry with { StartDate = DateTime.Parse(e.Value?.ToString() ?? DateTime.Today.ToString("yyyy-MM-dd")) })" />
         </div>
         <div class="form-group">
             <label>End Date</label>
             <input type="date" value="@(Entry.EndDate?.ToString("yyyy-MM-dd") ?? string.Empty)"
                    disabled="@IsCurrent"
                    @onchange="HandleEndDateChange" />
             <label class="checkbox-label">
                 <input type="checkbox" checked="@IsCurrent"
                        @onchange="e => OnCurrentChanged((bool)(e.Value ?? false))" />
                 Current position
             </label>
         </div>
     </div>
     <div class="form-group">
         <label>Description</label>
         <textarea rows="3" value="@Entry.Description"
                   @onchange="e => Update(Entry with { Description = e.Value?.ToString() ?? string.Empty })"></textarea>
     </div>
     @if (CanRemove)
     {
         <button type="button" class="btn-remove" @onclick="OnRemove">Remove</button>
     }
 </div>

 @code {
     [Parameter, EditorRequired] public WorkEntry Entry { get; set; } = default!;
     [Parameter] public bool CanRemove { get; set; }
     [Parameter] public EventCallback<WorkEntry> OnEntryChanged { get; set; }
     [Parameter] public EventCallback OnRemove { get; set; }

     private bool IsCurrent => Entry.EndDate is null;

     private void HandleEndDateChange(ChangeEventArgs e)
     {
         DateTime? endDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null;
         Update(Entry with { EndDate = endDate });
     }

     private void OnCurrentChanged(bool isCurrent)
     {
         var updated = isCurrent
             ? Entry with { EndDate = null }
             : Entry with { EndDate = DateTime.Today };
         Update(updated);
     }

     private async Task Update(WorkEntry updated)
     {
         await OnEntryChanged.InvokeAsync(updated);
     }
 }
